/**
 * Generate QCF Font Map
 * 
 * Creates lib/qcf-font-map.ts with static require() statements for all 604 QCF fonts.
 * React Native requires static require() at build time - dynamic paths don't work.
 * 
 * Usage: node scripts/generate-font-map.js
 */

const fs = require('fs');
const path = require('path');

const TOTAL_PAGES = 604;
const OUTPUT_PATH = path.join(__dirname, '../lib/qcf-font-map.ts');

function pad3(n) {
  return String(n).padStart(3, '0');
}

function generateFontMap() {
  const lines = [
    '/**',
    ' * QCF Font Map - Auto-generated',
    ' * ',
    ' * Static require() mapping for all 604 QCF Mushaf page fonts.',
    ' * These fonts are bundled with the app for offline access.',
    ' * ',
    ' * Generated by: scripts/generate-font-map.js',
    ' * DO NOT EDIT MANUALLY',
    ' */',
    '',
    'import { FontSource } from \'expo-font\';',
    '',
    '/**',
    ' * Map of page number (1-604) to font source.',
    ' * Use with Font.loadAsync() or Asset.fromModule().',
    ' */',
    'export const QCF_FONT_MAP: Record<number, FontSource> = {',
  ];

  // Generate require statements for each page
  for (let page = 1; page <= TOTAL_PAGES; page++) {
    const paddedPage = pad3(page);
    const comma = page < TOTAL_PAGES ? ',' : '';
    lines.push(`  ${page}: require('../assets/fonts/qcf/QCF4_tajweed_${paddedPage}.ttf')${comma}`);
  }

  lines.push('};');
  lines.push('');
  lines.push('/** Total number of Quran pages */');
  lines.push('export const TOTAL_QURAN_PAGES = 604;');
  lines.push('');
  lines.push('/** Check if a page number is valid */');
  lines.push('export function isValidPage(page: number): boolean {');
  lines.push('  return Number.isInteger(page) && page >= 1 && page <= TOTAL_QURAN_PAGES;');
  lines.push('}');
  lines.push('');

  return lines.join('\n');
}

// Generate and write the file
const content = generateFontMap();
fs.writeFileSync(OUTPUT_PATH, content);

console.log(`✅ Generated ${OUTPUT_PATH}`);
console.log(`   → ${TOTAL_PAGES} font mappings created`);
